// ---------- model ----------
const COUNTS = [-3, -2, -1, 0, 1, 2, 3, 4, 5, 6];
// today / a timestamp as YYYY-MM-DD in *your* time zone (toISOString would give the UTC date, a day ahead in the evening)
const localDay = (t = Date.now()) => { const d = new Date(t); return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`; };
const LABEL = (tc) => (tc === -3 ? "≤ −3" : tc === 6 ? "≥ +6" : tc > 0 ? `+${tc}` : tc < 0 ? `−${-tc}` : "0");
const DEFAULT_BETS = { "-3": 0, "-2": 0, "-1": 0, "0": 0, "1": 25, "2": 50, "3": 50, "4": 75, "5": 75, "6": 100 };
const fmtH = (h) => `${Math.round((Number(h) || 0) * 100) / 100}h`; // hours to the hundredth, no float noise
const sgnMoney = (v) => { const r = Math.round(v); return `${r > 0 ? "+" : r < 0 ? "−" : ""}$${Math.abs(r).toLocaleString()}`; };
const shortMoney = (v) => { const a = Math.abs(v), sg = v < 0 ? "−" : ""; return a >= 1000 ? `${sg}$${(a / 1000).toFixed(a >= 10000 ? 0 : 1)}k` : `${sg}$${Math.round(a)}`; };
function niceTicks(lo, hi, n = 5) { const span = hi - lo || 1; const raw = span / n; const mag = Math.pow(10, Math.floor(Math.log10(raw))); const e = raw / mag; const step = (e >= 7.5 ? 10 : e >= 3.5 ? 5 : e >= 1.5 ? 2 : 1) * mag; const out = []; for (let v = Math.ceil(lo / step) * step; v <= hi + step * 1e-9; v += step) out.push(+v.toFixed(10)); return out; }
const money = (n, d = 0) =>
  (n < 0 ? "−" : "") + "$" + Math.abs(n).toLocaleString(undefined, { maximumFractionDigits: d, minimumFractionDigits: d });
const pct = (x, d = 2) => (x * 100).toFixed(d) + "%";
const cash = (n) => money(n, Math.round(n * 100) % 100 ? 2 : 0);           // $5,037.50 only when there are cents
const sgnCash = (n) => (n > 0 ? "+" : n < 0 ? "−" : "") + cash(Math.abs(n));

// Calibrated model. Every number in CALR / CALQ was measured by a card-by-card Monte Carlo simulator playing BJA
// basic strategy, the Illustrious 18 and Fab 4 (Hi-Lo, half-deck true count truncated toward zero), insurance at +3,
// DAS, 3:2, dealer peeks, splits to 4 hands, aces split once — for every combination of decks, H17/S17, surrender and
// players at the table (CAL_ROUNDS below gives the millions of rounds behind each), every round tagged by its depth in
// the shoe so each penetration uses only the rounds that game actually deals (penetrations between the 5% grid points
// are interpolated). The simulator and the scripts that pack these tables are in tools/sim (see its README).
//   CALR[decks_h17_sur_players][pen] = per count: edge/hand, insurance's share, E[x²]/hand with and without
//                                      insurance, covariance of your two hands with and without insurance
//   CALQ[decks_players] (1–2 decks: decks_h17_sur_players)[pen] = share of rounds at each count, simulated separately for flat one-hand play, for
//                              sitting out (or, heads-up, leaving) at ≤ −3 … ≤ +1, and for two hands from +1 … +6;
//                              then cards per round for dealer + others and per hand of yours.
//   CALD[decks_h17_sur_players][pen] = single and double deck only: how each of those patterns shifts your edge at each count
//                              (with so few cards, where in the deck your rounds fall changes what a count is worth).
// Packed as little-endian uint16, quantized (see calRow).
// Millions of simulated rounds behind a game's edge and swing table: 6 and 8 decks are 400 heads-up and 600 pooled over
// tables of 2 to 7 (the edge at a count barely depends on how many others are playing); 4 decks 240; 1 and 2 decks 190.
const CAL_ROUNDS = (decks, seats) => (decks >= 6 ? (seats <= 1 ? 400 : 600) : decks === 4 ? 240 : 190);
