            <span className="mono barlab" style={{ "--i": i, fontSize: 8.5, color: on ? "var(--brass)" : x.b ? "var(--ivory-d)" : "var(--muted)", fontWeight: on ? 700 : 500 }}>{x.b ? (x.b >= 1000 ? `${x.b / 1000}k` : x.b) : "—"}</span>
